"""
Standalone branding seeder for OpenEMIS_DM.

Edit BRANDING_CONFIG below to set the branding values for your adaptation,
then run from the project root:

    python -m apps.app_db.scripts.app_db.seed_dm_OpenEMIS_branding
    python -m apps.app_db.scripts.app_db.seed_dm_OpenEMIS_branding --dry-run
    python -m apps.app_db.scripts.app_db.seed_dm_OpenEMIS_branding --force

Modes:
  default   — upsert: inserts missing keys, updates keys that already exist
  --force   — same as default (both insert and update)
  --dry-run — print what would happen without writing to the DB

This script is intentionally independent of seed_all.py and config.json.
"""

import argparse
import sys
from pathlib import Path

project_root = Path(__file__).resolve().parent.parent.parent.parent.parent
sys.path.insert(0, str(project_root))

from apps.app_db.constants.system_config import is_system_config_key
from apps.app_db.db.core import SessionLocal
from apps.app_db.models.core import SystemApplication, SystemConfiguration
from apps.shared.config.config import settings

# ---------------------------------------------------------------------------
# Edit these values for your adaptation of DFA DataManager
# ---------------------------------------------------------------------------
BRANDING_CONFIG: dict[str, dict[str, str]] = {
    "APP_NAME": {
        "value": "OpenEMIS DataManager",
        "description": "Application display name",
    },
    "APP_TITLE": {
        "value": "OpenEMIS DataManager",
        "description": "Application page title",
    },
    "FLAVOR_COLOR": {
        "value": "",
        "description": "Primary flavor color",
    },
    "FLAVOR_COLOR_HOVER": {
        "value": "",
        "description": "Flavor hover color",
    },
    "FLAVOR_FAVICON": {
        "value": "data:image/png;base64,",
        "description": "Favicon asset path or key",
    },
    "FLAVOR_LOGO": {
        "value": "data:image/png;base64,",
        "description": "Application logo asset path or key",
    },
    "APP_FOOTER_NOTE": {
        "value": "Copyright © 2023 OpenEMIS. All rights reserved.",
        "description": "Footer content displayed at the bottom of the application",
    },
}
# ---------------------------------------------------------------------------


def seed_branding(*, dry_run: bool) -> None:
    app_key = settings.DFA_DM_APP_KEY

    db = SessionLocal()
    try:
        app = db.query(SystemApplication).filter(SystemApplication.app_key == app_key).first()
        if app is None:
            print(f"Application with app_key '{app_key}' not found in system_applications. Aborting.")
            return

        keys = list(BRANDING_CONFIG.keys())
        existing_rows = (
            db.query(SystemConfiguration)
            .filter(
                SystemConfiguration.app_key == app_key,
                SystemConfiguration.key_code.in_(keys),
            )
            .all()
        )
        existing_by_key: dict[str, SystemConfiguration] = {row.key_code: row for row in existing_rows}

        if dry_run:
            would_insert = [k for k in keys if k not in existing_by_key]
            would_update = [k for k in keys if k in existing_by_key]
            print(f"[Dry run] app_key={app_key} — would insert {len(would_insert)}, would update {len(would_update)}")
            for k in would_insert:
                print(f"  INSERT  {k} = {BRANDING_CONFIG[k]['value']!r}")
            for k in would_update:
                old = existing_by_key[k].key_value or ""
                new = BRANDING_CONFIG[k]["value"]
                marker = " (no change)" if old == new else f" (was {old!r})"
                print(f"  UPDATE  {k} = {new!r}{marker}")
            return

        inserted = 0
        updated = 0
        unchanged = 0
        for key_code, meta in BRANDING_CONFIG.items():
            new_value = meta["value"]
            description = meta["description"]
            row = existing_by_key.get(key_code)
            if row is None:
                db.add(
                    SystemConfiguration(
                        app_key=app_key,
                        key_code=key_code,
                        key_value=new_value,
                        description=description,
                        is_system=is_system_config_key(key_code),
                    )
                )
                inserted += 1
            elif (row.key_value or "") != new_value:
                row.key_value = new_value
                updated += 1
            else:
                unchanged += 1

        db.commit()
        print(
            f"Branding seeded for app_key='{app_key}': "
            f"inserted {inserted}, updated {updated}, unchanged {unchanged}."
        )
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Seed DFA_DM branding configuration (APP_NAME, APP_TITLE, FLAVOR_*, APP_FOOTER_NOTE)."
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Print what would be done without writing to the database.",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Alias for the default upsert behaviour (included for CLI consistency; values are always upserted).",
    )
    args = parser.parse_args()
    seed_branding(dry_run=args.dry_run)


if __name__ == "__main__":
    main()
